starter.css:
/* reset */
* { box-sizing: border-box; }
h2 { margin: 0 0 0.5rem; }

/* components */
.schedule .session-card .badge {
  display: inline-block;
  padding: 0.2em 0.7em;
  border-radius: 999px;
  background: #ede9fe;
  color: #5b21b6;
}

/* utilities: these should always win */
.bg-accent { background: #fde68a; }

solution.css:
@layer reset, components, utilities;

@layer reset {
  * { box-sizing: border-box; }
  h2 { margin: 0 0 0.5rem; }
}

@layer components {
  .schedule .session-card .badge {
    display: inline-block;
    padding: 0.2em 0.7em;
    border-radius: 999px;
    background: #ede9fe;
    color: #5b21b6;
  }
}

@layer utilities {
  .bg-accent { background: #fde68a; }
}
